<?php require_once __DIR__.'/config/config.php';require_admin();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$p=$_POST['password']??'';$p2=$_POST['password2']??'';if(strlen($p)<8)$msg='رمز باید حداقل ۸ حرف باشد.';elseif($p!==$p2)$msg='تکرار رمز یکسان نیست.';else{$pdo->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($p,PASSWORD_DEFAULT),$_SESSION['admin_id']]);$msg='رمز مدیر تغییر کرد.';}}require 'partials/header.php';?><div class="panel"><h2>امنیت حساب مدیر</h2><p class="muted">نام کاربری فعلی: <?=h($_SESSION['admin_name']??'مدیر')?></p><?php if($msg):?><div class="alert" style="background:#eaf7f3;color:#0f766e"><?=h($msg)?></div><?php endif;?><form method="post" style="max-width:500px"><label>رمز جدید<input type="password" name="password" required></label><label>تکرار رمز جدید<input type="password" name="password2" required></label><button>تغییر رمز</button></form></div><?php require 'partials/footer.php';?>
